// Telleroo posts { webhook: { type, pay_run_id | transaction_id, idempotent_key } }.
const TYPES = ['payment_sent', 'payment_failed', 'payment_cancelled', 'pay_run_awaiting_approval', 'pay_run_approved', 'pay_run_payments_sent'];
const out = [];
for (const item of $input.all()) {
  const w = item.json.body?.webhook ?? {};
  if (!TYPES.includes(w.type)) continue;
  const ref = w.pay_run_id ?? w.transaction_id ?? '';
  out.push({ json: {
    dedupe_key: `${w.type}:${ref}:${w.idempotent_key ?? ''}`,
    event_type: w.type,
    pay_run_id: w.pay_run_id ?? null,
    transaction_id: w.transaction_id ?? null,
    idempotent_key: w.idempotent_key ?? null,
    payload: w,
  } });
}
return out;

