insert into public.telleroo_events (dedupe_key, event_type, pay_run_id, transaction_id, idempotent_key, payload)
select dedupe_key, event_type, pay_run_id, transaction_id, idempotent_key, payload
from jsonb_to_record($1::jsonb) as r(dedupe_key text, event_type text, pay_run_id text, transaction_id text, idempotent_key text, payload jsonb)
on conflict (dedupe_key) do nothing;

