// Keep what the app needs; bank account numbers cut to the last 4 digits.
const last4 = (v) => { const d = String(v ?? '').replace(/\D/g, ''); return d ? d.slice(-4) : null; };
const pounds = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v).toFixed(2));
const out = [];
for (const item of $input.all()) {
  const p = item.json.payrun;
  if (!p?.id) continue;
  const payments = [];
  for (const state of ['initialized', 'accepted', 'rejected']) {
    for (const x of p[`${state}_payments`] ?? []) {
      payments.push({
        state,
        amount: x.amount === '' || x.amount == null ? null : String(x.amount),
        payeeName: x.payee_name ?? null,
        accountLast4: last4(x.account_no ?? x.iban),
        reference: x.reference ?? null,
        idempotentKey: x.idempotent_key ?? null,
        info: x.info ?? null,
      });
    }
  }
  out.push({ json: {
    telleroo_id: p.id,
    idempotent_key: p.idempotent_key ?? null,
    name: p.name ?? null,
    account_id: p.account_id ?? null,
    status: p.status ?? 'unknown',
    payees_type: p.payees_type ?? null,
    payments_reason: p.payments_reason ?? null,
    scheduled_for: p.scheduled_for ?? null,
    requested_amount: pounds(p.requested_amount),
    accepted_amount: pounds(p.accepted_amount),
    paid_amount: pounds(p.paid_amount),
    due_amount: pounds(p.due_amount),
    currency: p.currency_code ?? null,
    payments,
    telleroo_url: p.deeplink?.telleroo_payrun ?? null,
    telleroo_created_at: p.created_at ?? null,
  } });
}
return out;
